import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

#define TRIPLET_EPS 1e-6f
#define BLOCK_THREADS 512
#define WARPS_PER_BLOCK (BLOCK_THREADS / 32)

__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ out,
    const int B,
    const int N,
    const float margin,
    const float invB
) {
    const int row = blockIdx.x;
    if (row >= B) return;

    const size_t base = (size_t)row * (size_t)N;
    const float* a = anchor + base;
    const float* p = positive + base;
    const float* n = negative + base;

    float acc_pos = 0.0f;
    float acc_neg = 0.0f;

    const int nvec = N >> 2;
    const float4* a4 = reinterpret_cast<const float4*>(a);
    const float4* p4 = reinterpret_cast<const float4*>(p);
    const float4* n4 = reinterpret_cast<const float4*>(n);

    for (int i = threadIdx.x; i < nvec; i += BLOCK_THREADS) {
        const float4 av = a4[i];
        const float4 pv = p4[i];
        const float4 nv = n4[i];

        const float dp0 = av.x - pv.x + TRIPLET_EPS;
        const float dp1 = av.y - pv.y + TRIPLET_EPS;
        const float dp2 = av.z - pv.z + TRIPLET_EPS;
        const float dp3 = av.w - pv.w + TRIPLET_EPS;

        const float dn0 = av.x - nv.x + TRIPLET_EPS;
        const float dn1 = av.y - nv.y + TRIPLET_EPS;
        const float dn2 = av.z - nv.z + TRIPLET_EPS;
        const float dn3 = av.w - nv.w + TRIPLET_EPS;

        acc_pos += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
        acc_neg += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
    }

    for (int j = (nvec << 2) + threadIdx.x; j < N; j += BLOCK_THREADS) {
        const float dp = a[j] - p[j] + TRIPLET_EPS;
        const float dn = a[j] - n[j] + TRIPLET_EPS;
        acc_pos += dp * dp;
        acc_neg += dn * dn;
    }

    #pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        acc_pos += __shfl_down_sync(0xffffffffu, acc_pos, off);
        acc_neg += __shfl_down_sync(0xffffffffu, acc_neg, off);
    }

    __shared__ float shared_pos[WARPS_PER_BLOCK];
    __shared__ float shared_neg[WARPS_PER_BLOCK];

    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;

    if (lane == 0) {
        shared_pos[warp] = acc_pos;
        shared_neg[warp] = acc_neg;
    }
    __syncthreads();

    if (warp == 0) {
        acc_pos = (lane < WARPS_PER_BLOCK) ? shared_pos[lane] : 0.0f;
        acc_neg = (lane < WARPS_PER_BLOCK) ? shared_neg[lane] : 0.0f;

        #pragma unroll
        for (int off = WARPS_PER_BLOCK / 2; off > 0; off >>= 1) {
            acc_pos += __shfl_down_sync(0xffffffffu, acc_pos, off);
            acc_neg += __shfl_down_sync(0xffffffffu, acc_neg, off);
        }

        if (lane == 0) {
            const float d_pos = sqrtf(acc_pos);
            const float d_neg = sqrtf(acc_neg);
            const float loss = fmaxf(d_pos - d_neg + margin, 0.0f);
            atomicAdd(out, loss * invB);
        }
    }
}

torch::Tensor triplet_margin_loss_forward(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin) {
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(anchor.scalar_type() == at::kFloat && positive.scalar_type() == at::kFloat && negative.scalar_type() == at::kFloat, "inputs must be float32");
    TORCH_CHECK(anchor.dim() == 2 && positive.dim() == 2 && negative.dim() == 2, "inputs must be 2D [batch, features]");
    TORCH_CHECK(anchor.is_contiguous() && positive.is_contiguous() && negative.is_contiguous(), "inputs must be contiguous");

    const int64_t B64 = anchor.size(0);
    const int64_t N64 = anchor.size(1);
    TORCH_CHECK(positive.size(0) == B64 && positive.size(1) == N64, "positive shape mismatch");
    TORCH_CHECK(negative.size(0) == B64 && negative.size(1) == N64, "negative shape mismatch");
    TORCH_CHECK(B64 <= 0x7fffffffLL && N64 <= 0x7fffffffLL, "shape too large");

    c10::cuda::CUDAGuard guard(anchor.device());
    auto out = at::empty({}, anchor.options());

    const int B = (int)B64;
    const int N = (int)N64;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    cudaMemsetAsync(out.data_ptr<float>(), 0, sizeof(float), stream);

    if (B > 0) {
        dim3 grid((unsigned)B);
        dim3 block(BLOCK_THREADS);
        triplet_margin_loss_kernel<<<grid, block, 0, stream>>>(
            anchor.data_ptr<float>(),
            positive.data_ptr<float>(),
            negative.data_ptr<float>(),
            out.data_ptr<float>(),
            B,
            N,
            (float)margin,
            1.0f / (float)B
        );
        C10_CUDA_KERNEL_LAUNCH_CHECK();
    }
    return out;
}
"""

_triplet_cuda = load_inline(
    name="triplet_margin_loss_single_kernel",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["triplet_margin_loss_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        return _triplet_cuda.triplet_margin_loss_forward(anchor, positive, negative, self.margin)

